//! Reference vectors generated by `node scripts/check-engine-parity.mjs --write-vectors`.
use voice_simulator_core::renderer::AnyRenderer;

fn check(json: &str) {
    // The generator writes four numeric arrays, one per line. Keeping this
    // deliberately small avoids a JSON dependency in the numerical core.
    let arrays: Vec<Vec<f64>> = json
        .lines()
        .skip(1)
        .take(4)
        .map(|line| {
            line.trim_end_matches(',')
                .trim_start_matches('[')
                .trim_end_matches(']')
                .split(',')
                .filter(|v| !v.is_empty())
                .map(|v| v.parse().unwrap())
                .collect()
        })
        .collect();
    let model: Vec<u8> = arrays[1].iter().map(|v| *v as u8).collect();
    let mut renderer = AnyRenderer::new(&arrays[0], &model).unwrap();
    let mut samples = vec![0.0; arrays[3].len()];
    assert_eq!(
        renderer.render(&arrays[2], &mut samples).unwrap(),
        samples.len()
    );
    let mut maximum = 0.0f64;
    for (actual, expected) in samples.iter().zip(&arrays[3]) {
        assert!(actual.is_finite());
        maximum = maximum.max((f64::from(*actual) - expected).abs());
    }
    assert!(maximum <= 1e-4, "max sample error {maximum}");
}

macro_rules! vector {
    ($name:ident, $id:literal) => {
        #[test]
        fn $name() {
            check(include_str!(concat!("vectors/", $id, ".json")));
        }
    };
}
vector!(folds, "source.folds");
vector!(interaction, "source.tract-interaction");
vector!(subglottal, "source.subglottal");
vector!(whisper, "mode.whisper");
vector!(sheet, "solver.fdtd2d");
